-- Retention is no longer held back: every invoice owes its whole amount once it is sent.
ALTER TABLE client DROP COLUMN retention_pct;
ALTER TABLE invoice DROP COLUMN retention_pct;
ALTER TABLE invoice DROP COLUMN retention_cap;
ALTER TABLE invoice DROP COLUMN retention_released_on;
ALTER TABLE invoice DROP COLUMN retention_released_amount;
ALTER TABLE invoice DROP COLUMN credit_retention;
-- A draft spread over monthly instalments: how many (2 to 24; null when there is no plan) and the
-- annual interest rate (0 to 30, up to two decimals) the schedule is worked out at.
ALTER TABLE invoice ADD COLUMN instalments INT;
ALTER TABLE invoice ADD COLUMN instalment_rate DECIMAL(5, 2) DEFAULT 0 NOT NULL;
-- The instalment of a plan the client skipped (it pays only its interest, and the instalments after
-- it are worked out again); null when none was.
ALTER TABLE invoice ADD COLUMN skipped_instalment INT;
package net.officefloor.hq.app.invoices;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * One instalment of an invoice's plan: its number (from 1), the day it falls due, what is paid, the
 * interest and principal it is made of, and the balance still owed after it; money to the cent.
 */
public record Instalment(int number, LocalDate dueDate, BigDecimal payment, BigDecimal interest,
        BigDecimal principal, BigDecimal balance) {

    /** Where an instalment is: paid off, part paid, overdue (more than the grace period past due) or due. */
    public enum Status {
        PAID, PART_PAID, OVERDUE, DUE
    }

    /**
     * What has been paid off an instalment, what is still unpaid on it, the late interest it has been
     * charged and what of it is still unpaid, and its status on a day.
     */
    public record Progress(Instalment instalment, BigDecimal paid, BigDecimal unpaid, BigDecimal lateInterest,
            BigDecimal interestUnpaid, Status status) {

        /** All still owed on the instalment: what is unpaid on it and its late interest. */
        public BigDecimal owed() {
            return unpaid.add(interestUnpaid);
        }

        /** What is still unpaid of the late interest the instalment has been charged. */
        public BigDecimal chargesUnpaid() {
            return interestUnpaid;
        }
    }
}
